+            {
+                freq.TryGetValue(word, out var count);
+                freq[word] = count + 1;
+            }
+        }
+
+        return freq;
+    }
+
+    private static List<double> ScoreSentences(
+        List<string> sentences,
+        Dictionary<string, int> wordFrequencies)
+    {
+        var scores = new List<double>(sentences.Count);
+
+        foreach (var sentence in sentences)
+        {
+            var words = Tokenize(sentence);
+            double score = words.Count == 0
+                ? 0
+                : words.Sum(w => wordFrequencies.GetValueOrDefault(w, 0)) / (double)words.Count;
+            scores.Add(score);
+        }
+
+        return scores;
+    }
+
+    private static List<string> Tokenize(string sentence)
+    {
+        return System.Text.RegularExpressions.Regex
+            .Matches(sentence, @"\b[a-zA-Z]{2,}\b")
+            .Select(m => m.Value.ToLowerInvariant())
+            .ToList();
+    }
+}
